def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    if b_idx.numel() <= 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax_temperature_scaled'})
    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]
    # Adaptive temperature scaling parameter tau, default 1.0 or override
    base_tau = float(extra.get('weight_tau', 1.0))
    # Compute per-instance gap std dev (safely fallback)
    instance_std = feature_cache.get('instance_obj_std', None)
    if instance_std is not None and instance_std.numel() == objective.size(0):
        tau = base_tau * (instance_std[b_idx].clamp_min(1e-3))
    else:
        tau = base_tau
    weight_raw = (gap / tau).exp()
    weight = torch.nan_to_num(weight_raw, nan=0.0, posinf=10.0, neginf=0.0).clamp(0.25, 6.0)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax_temperature_scaled'})

